#!/usr/bin/env python3
"""Render the hand-DDL of the local draft table from the upstream TABL definition.

The main README tells a user who installs by copy & paste ("Option B") to
create the persistence table by hand and carries the DDL for it. That block
used to be written by hand too, and drifted: when upstream added the UNAME
column to z2ui5_t_01 the folded class started reading it while the README
still listed the old seven columns, so a table created from the README
failed the class activation. The table definition this repository ships is
input/01/01/z2ui5_t_01.tabl.xml (abapGit's TABL serialisation), renamed to
z2ui5_t_99 by build_locals_imp.py - so the DDL is rendered from that file,
and generate_branch.yaml checks the README against it the way it checks
everything else it ships.

Usage: table_ddl.py <z2ui5_t_01.tabl.xml> [--check README.md | --write README.md]

Without a flag the DDL block is printed. --check exits 1 when README.md does
not carry exactly this block between the DDL markers, --write replaces it.
"""

import re
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

LOCAL_NAME = 'z2ui5_t_99'
LABEL = 'abap2UI5-local'
BEGIN = '<!-- table-ddl: generated by .github/scripts/table_ddl.py from input/01/01/z2ui5_t_01.tabl.xml - do not edit -->'
END = '<!-- /table-ddl -->'

# abapGit writes a field either with a data element (ROLLNAME) or with the
# built-in type (DATATYPE + LENG). The data elements the table uses map to
# their CDS built-in types; a new one stops the build here, on purpose.
ROLLNAMES = {
    'MANDT': 'abap.clnt',
    'TIMESTAMPL': 'timestampl',
}
DATATYPES = {
    'CHAR': lambda leng: f'abap.char({int(leng)})',
    'STRG': lambda leng: 'abap.string(0)',
}


def render(tabl_xml: Path) -> str:
    root = ET.parse(tabl_xml).getroot()
    fields = []
    for f in root.iter('DD03P'):
        name = f.findtext('FIELDNAME').lower()
        key = f.findtext('KEYFLAG') == 'X'
        rollname = f.findtext('ROLLNAME')
        if rollname:
            assert rollname in ROLLNAMES, f'{name}: data element {rollname} has no CDS mapping in table_ddl.py'
            typ = ROLLNAMES[rollname]
        else:
            datatype = f.findtext('DATATYPE')
            assert datatype in DATATYPES, f'{name}: built-in type {datatype} has no CDS mapping in table_ddl.py'
            typ = DATATYPES[datatype](f.findtext('LENG') or '0')
        if f.findtext('NOTNULL') == 'X':
            typ += ' not null'
        fields.append((('key ' if key else '') + name, typ))
    width = max(len(n) for n, _ in fields)
    lines = [
        '```cds',
        f"@EndUserText.label : '{LABEL}'",
        '@AbapCatalog.enhancement.category : #NOT_EXTENSIBLE',
        '@AbapCatalog.tableCategory : #TRANSPARENT',
        '@AbapCatalog.deliveryClass : #A',
        '@AbapCatalog.dataMaintenance : #RESTRICTED',
        f'define table {LOCAL_NAME} {{',
    ]
    lines += [f'  {n.ljust(width)} : {t};' for n, t in fields]
    lines += ['}', '```']
    return '\n'.join(lines)


def main(argv):
    if len(argv) < 2:
        sys.exit(__doc__)
    block = f'{BEGIN}\n{render(Path(argv[1]))}\n{END}'
    if len(argv) == 2:
        print(block)
        return
    mode, readme = argv[2], Path(argv[3])
    text = readme.read_text(encoding='utf-8')
    pattern = re.compile(re.escape(BEGIN) + r'.*?' + re.escape(END), re.S)
    if not pattern.search(text):
        sys.exit(f'{readme}: no table-ddl markers found')
    new = pattern.sub(lambda _: block, text)
    if mode == '--write':
        readme.write_text(new, encoding='utf-8')
        print(f'{readme}: table DDL written')
    elif mode == '--check':
        if new != text:
            sys.exit(f'{readme}: the table DDL is out of date - run\n'
                     f'  python3 .github/scripts/table_ddl.py {argv[1]} --write {readme}')
        print(f'{readme}: table DDL matches {argv[1]}')
    else:
        sys.exit(__doc__)


if __name__ == '__main__':
    main(sys.argv)
